/**
 * Determines the next active side in the turn order.
 * Cycles through sides in order, wrapping around when reaching the end.
 */
export function nextActiveSide(state: MatchState): Side {
  // Count how many distinct sides have living tokens
  const sidesWithTokens = new Set<Side>();
  for (const token of state.tokens) {
    if (token.kind === 'unit' && token.hp > 0) {
      sidesWithTokens.add(token.side);
    } else if (token.kind === 'squadron' && token.hpPool > 0) {
      sidesWithTokens.add(token.side);
    }
  }
  
  // If no sides have tokens, return 0
  if (sidesWithTokens.size === 0) {
    return 0;
  }
  
  // Cycle through sides in order
  const sortedSides = Array.from(sidesWithTokens).sort((a, b) => a - b);
  const currentSideIndex = sortedSides.indexOf(state.activeSide);
  const nextIndex = (currentSideIndex + 1) % sortedSides.length;
  
  return sortedSides[nextIndex];
}